/*
  gzip 스트림 3종의 실제 바이트. base64로 구워 두고 gzipStreams.test.ts가
  같은 레시피로 재압축해 대조한다 — 화면에 그려지는 격자가 곧 테스트가 재생성한 바이트다.

  기준선은 level 9이고 firstDiff·diffCount는 그것과의 차이다. 어느 레벨이 BuildKit·데몬의
  실제 설정인지는 확인하지 않았다 — 데모가 보이는 건 "설정이 다르면 바이트가 갈린다"뿐이다.

  이 데모가 주장하지 않는 것: "docker의 gzip과 BuildKit의 gzip이 헤더 1바이트만 다르다".
  digests.ts가 밝힌 대로 페이로드는 결정적 대역물이다. 데모가 말하는 것은
  "설정이 조금 다르면 헤더 1바이트, 많이 다르면 데이터 전체 — 어느 쪽이든 digest는 완전히 갈린다"다.

  MTIME(바이트 4~7)이 0이고, 테스트가 같은 zlib으로 재압축해 바이트 대조로 잠근다.
  zlib 구현이 바뀌어 출력이 달라지면 테스트가 먼저 깨진다 — 그게 재현 가능성의 실제 보증이다.
*/

/** 이 스트림들은 옵션 필드가 없어 gzip 헤더가 10바이트다. XFL(오프셋 8)이 압축 레벨에 따라 달라진다. */
export const GZIP_HEADER_BYTES = 10;

export interface Stream {
  level: number;
  bytes: number;
  /** level 9와 처음 달라지는 오프셋. 같으면 -1 */
  firstDiff: number;
  /** level 9와 다른 바이트 수(길이 차 포함) */
  diffCount: number;
  b64: string;
}

export const STREAMS: Stream[] = [
  { level: 9, bytes: 621, firstDiff: -1, diffCount: 0,
    b64: "" },
  { level: 6, bytes: 621, firstDiff: 8, diffCount: 1,
    b64: "" },
  { level: 1, bytes: 1404, firstDiff: 8, diffCount: 1391,
    b64: "" },
];

export const LABELS: Record<number, { title: string; hint: string }> = {
  9: { title: "level 9", hint: "기준선" },
  6: { title: "level 6", hint: "설정이 조금 다를 때" },
  1: { title: "level 1", hint: "설정이 크게 다를 때" },
};

/** base64를 바이트로 되돌린다. 브라우저·node 양쪽에서 동작해야 한다(테스트가 node) */
export function decode(b64: string): Uint8Array {
  if (typeof atob === "function") {
    const s = atob(b64);
    const out = new Uint8Array(s.length);
    for (let i = 0; i < s.length; i++) out[i] = s.charCodeAt(i);
    return out;
  }
  return new Uint8Array(Buffer.from(b64, "base64"));
}
